public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }





    @Test
    public void testEscape_NonAsciiCharacters() throws IOException {
        StringWriter writer = new StringWriter();
        // Character > 0x7F (e.g., Unicode \u0080)
        // Assuming entityName(0x80) returns null
        String input = "\u0080";
        entities.escape(writer, input);
        Assert.assertEquals("&#128;", writer.toString());
    }










}

package org.apache.commons.lang;

import java.io.*;
