import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }







    @Test
    public void testEscape_MixedContent() throws IOException {
        StringWriter writer = new StringWriter();
        // Mix of: 1. Known entity, 2. Standard ASCII, 3. Non-ASCII (No entity)
        // We use a character that is definitely not a standard entity but > 0x7F
        String input = "A< \u0080"; 
        entities.escape(writer, input);
        String result = writer.toString();

        // Logic path coverage:
        // 1. entityName != null -> &...;
        // 2. entityName == null && c <= 0x7F -> c
        // 3. entityName == null && c > 0x7F -> &#...;
        Assert.assertTrue(result.contains("A"));
        Assert.assertTrue(result.contains("&"));
        Assert.assertTrue(result.contains("&#128;"));
    }








}

