import static org.junit.Assert.*;

public class Entities_escape_TriageGen1Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }















    @Test
    public void testEscape_IOException() throws IOException {
        // Custom Writer that throws IOException
        Writer throwingWriter = new Writer() {
            @Override
            public void write(char[] cbuf, int off, int len) throws IOException {
                throw new IOException("Simulated failure");
            }

            @Override
            public void flush() throws IOException {}

            @Override
            public void close() throws IOException {}
        };

        try {
            entities.escape(throwingWriter, "test");
            Assert.fail("Should have thrown IOException");
        } catch (IOException e) {
            Assert.assertEquals("Simulated failure", e.getMessage());
        }
    }
}
